"  const handleCancelLesson = async (scheduleId?: string) => {
    const targetId = scheduleId || nextLesson?.id;
    if (!targetId) return;
    if (!confirm('Möchtest du diesen Unterrichtstermin wirklich absagen?')) return;
    try {
      await supabase
        .from('schedules')
        .update({ status: 'canceled_by_student' })
        .eq('id', targetId);
      await fetchAllData();
      alert('Unterricht erfolgreich abgesagt.');
    } catch (err) {
      console.error(err);
      alert('Unterricht erfolgreich abgesagt.');
    }
  };

  const handleRescheduleLesson = async (scheduleId?: string) => {
    const targetId = scheduleId || nextLesson?.id;
    if (!targetId) return;
    if (!confirm('Möchtest du für diesen Unterrichtstermin einen Ersatztermin anfragen? Dein Lehrer wird benachrichtigt.')) return;
    try {
      await supabase
        .from('schedules')
        .update({ status: 'pending_reschedule' })
        .eq('id', targetId);
      await fetchAllData();
      alert('Verschiebungs-Anfrage erfolgreich gesendet. Dein Lehrer entscheidet darüber.');
    } catch (err) {
      console.error(err);
      alert('Fehler beim Senden der Verschiebe-Anfrage.');
    }
  };"

